commandLine.original:
$ErrorActionPreference='Stop'; $tmp = Join-Path $env:TEMP 'pdfread'; New-Item -ItemType Directory -Force -Path $tmp | Out-Null; Set-Location $tmp; dotnet new console --force | Out-Null; dotnet add package PdfPig --version 0.1.9 | Out-Null; @'
using System;
using System.IO;
using UglyToad.PdfPig;

var pdf = Path.Combine("d:\\dev\\Nemetschek", "Task .NET 2026.pdf");
if (!File.Exists(pdf)) { Console.WriteLine("PDF_NOT_FOUND"); return; }
using var document = PdfDocument.Open(pdf);
foreach (var page in document.GetPages())
{
    Console.WriteLine(page.Text);
}
'@ | Set-Content -Path Program.cs; dotnet run --project . --no-restore

